// @FIGURE_CODE_BEGIN
/* ── ELEMENT SPEC ────────────────────────────────────────────────────────────
// tetra edges (x2 copies)   → CylinderGeometry rods r=0.018, front edge r=0.045, magenta #EC0F8C
// tetra interior solid      → rod r=0.030 black   (near-bottom-front vertex → body centre)
// tetra interior thin       → rod r=0.012 black   (apex → body centre)
// tetra interior dashed     → 6 short rods r=0.014 black (rear vertex → body centre)
// inscribed CH4             → Sphere C r=0.32 / H r=0.20 + rods r=0.05, MeshStandardMaterial, faded
// 109.5° arc                → TubeGeometry along slerp arc + HTML label
// notation C / 4×H          → HTML labels (addLabel), serif, in billboarded group
// plain bonds (up,right)    → rods r=0.022 black, billboard plane
// dashed bond (left)        → 5 short rods r=0.022 black
// wedge bond (down)         → ShapeGeometry quad, 0.024 → 0.22 wide, black
// leader lines + arrows     → rods r=0.011 + ConeGeometry heads, black
// ball & stick              → Sphere C r=0.45 #4C4C4C, H r=0.30 #E5E2DA, rods r=0.07 #B9C2CC
// curly brace               → TubeGeometry on CatmullRomCurve3, black r=0.018
// click proxies             → CylinderGeometry r≈0.22, opacity 0 (invisible, raycastable)
─────────────────────────────────────────────────────────────────────────────*/

const COL = { mag: 0xEC0F8C, blk: 0x000000, amber: 0xFFA726, C: 0x4C4C4C, H: 0xE5E2DA, rod: 0xB9C2CC };

/* screen-horizontal axis (maps to pure screen X under the isometric pose) */
const SQ = Math.SQRT1_2;
const AXU = new THREE.Vector3(SQ, 0, -SQ);
const AXW = new THREE.Vector3(SQ, 0, SQ);
function P(s, y, t) { t = t || 0; return new THREE.Vector3(AXU.x * s + AXW.x * t, y, AXU.z * s + AXW.z * t); }

function rodMesh(a, b, r, mat, seg) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = Math.max(dir.length(), 1e-5);
  const geo = new THREE.CylinderGeometry(r, r, len, seg || 12, 1);
  geo.translate(0, len / 2, 0);
  const m = new THREE.Mesh(geo, mat);
  m.position.copy(a);
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  return m;
}
function dashRods(a, b, r, mat, n) {
  const g = new THREE.Group();
  for (let i = 0; i < n; i++) {
    const t0 = (2 * i) / (2 * n - 1), t1 = (2 * i + 1) / (2 * n - 1);
    g.add(rodMesh(a.clone().lerp(b, t0), a.clone().lerp(b, t1), r, mat, 8));
  }
  return g;
}
function proxyMat() {
  return new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false });
}

/* ── lights ─────────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 1.15));
const keyLight = new THREE.DirectionalLight(0xffffff, 2.3); keyLight.position.set(5, 7, 8); scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.7); fillLight.position.set(-6, 2, -5); scene.add(fillLight);

const billboards = [];
const dynLabels = [];
const labelsA = [], labelsB = [];

/* ── PANEL A : regular tetrahedra ───────────────────────────────────────── */
const panelA = new THREE.Group(); scene.add(panelA);
const matMagA = new THREE.MeshBasicMaterial({ color: COL.mag, transparent: true });
const matBlkA = new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true });

const TA = 2.2, TR = TA / Math.sqrt(3), TH = TA * Math.sqrt(2 / 3), TYB = -0.95;
function tetraVerts() {
  return {
    b0: new THREE.Vector3(0, TYB, TR),
    b1: new THREE.Vector3(-TR * 0.8660254, TYB, -TR * 0.5),
    b2: new THREE.Vector3(TR * 0.8660254, TYB, -TR * 0.5),
    ap: new THREE.Vector3(0, TYB + TH, 0),
    c: new THREE.Vector3(0, TYB + TH / 4, 0)
  };
}
function buildTetra(s, interior) {
  const g = new THREE.Group();
  g.position.copy(P(s, 0, 0));
  g.rotation.y = Math.PI / 4;
  const v = tetraVerts();
  const E = [[v.b0, v.b1, 0.046], [v.b1, v.b2, 0.018], [v.b2, v.b0, 0.018],
             [v.ap, v.b0, 0.018], [v.ap, v.b1, 0.018], [v.ap, v.b2, 0.018]];
  E.forEach(e => g.add(rodMesh(e[0], e[1], e[2], matMagA)));
  if (interior) {
    g.add(rodMesh(v.b0, v.c, 0.030, matBlkA));
    g.add(rodMesh(v.ap, v.c, 0.012, matBlkA));
    g.add(dashRods(v.b1, v.c, 0.014, matBlkA, 6));
  }
  panelA.add(g);
  return g;
}
const tetra1 = buildTetra(-5.85, false);
const tetra2 = buildTetra(-3.15, true);

/* inscribed methane inside the second tetrahedron */
const inscG = new THREE.Group(); tetra2.add(inscG);
const matCin = new THREE.MeshStandardMaterial({ color: COL.C, roughness: 0.4, metalness: 0.1, transparent: true });
const matHin = new THREE.MeshStandardMaterial({ color: COL.H, roughness: 0.35, metalness: 0.05, transparent: true });
const matRin = new THREE.MeshStandardMaterial({ color: COL.rod, roughness: 0.5, metalness: 0.1, transparent: true });
{
  const v = tetraVerts();
  const cs = new THREE.Mesh(new THREE.SphereGeometry(0.32, 28, 20), matCin);
  cs.position.copy(v.c); inscG.add(cs);
  [v.b0, v.b1, v.b2, v.ap].forEach(p => {
    inscG.add(rodMesh(v.c, p, 0.05, matRin, 12));
    const h = new THREE.Mesh(new THREE.SphereGeometry(0.20, 24, 16), matHin);
    h.position.copy(p); inscG.add(h);
  });
  // 109.5° arc between the bond to the front-bottom vertex and the bond to the apex
  const d1 = v.b0.clone().sub(v.c).normalize();
  const d2 = v.ap.clone().sub(v.c).normalize();
  const ang = d1.angleTo(d2);
  const axis = new THREE.Vector3().crossVectors(d1, d2).normalize();
  const pts = [];
  for (let i = 0; i <= 26; i++) pts.push(d1.clone().applyAxisAngle(axis, ang * i / 26).multiplyScalar(0.58).add(v.c));
  const arcMat = new THREE.MeshBasicMaterial({ color: 0x222222, transparent: true });
  inscG.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 60, 0.013, 6, false), arcMat));
  var angleLabelLocal = d1.clone().applyAxisAngle(axis, ang / 2).multiplyScalar(0.86).add(v.c);
}

/* ── PANEL B : flat notation + model ────────────────────────────────────── */
const panelB = new THREE.Group(); scene.add(panelB);

const mark = {
  up: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  right: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  left: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  down: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true, side: THREE.DoubleSide })
};
