  up: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  right: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  left: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  down: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true })
};
const BONDS = {
  up: { mats: [mark.up, lead.up], labels: [], rodMat: null, hMat: null },
  right: { mats: [mark.right, lead.right], labels: [], rodMat: null, hMat: null },
  left: { mats: [mark.left, lead.left], labels: [], rodMat: null, hMat: null },
  down: { mats: [mark.down, lead.down], labels: [], rodMat: null, hMat: null }
};

const notation = new THREE.Group();
notation.position.copy(P(1.5, 0.15, 0));
panelB.add(notation); billboards.push(notation);

const V2 = (x, y) => new THREE.Vector3(x, y, 0);

notation.add(rodMesh(V2(0, 0.30), V2(0, 0.88), 0.022, mark.up, 10));
notation.add(rodMesh(V2(0.30, 0), V2(0.88, 0), 0.022, mark.right, 10));
notation.add(dashRods(V2(-0.30, 0), V2(-0.88, 0), 0.022, mark.left, 5));
{
  const sh = new THREE.Shape();
  sh.moveTo(-0.014, -0.30); sh.lineTo(0.014, -0.30); sh.lineTo(0.11, -0.90); sh.lineTo(-0.11, -0.90); sh.closePath();
  notation.add(new THREE.Mesh(new THREE.ShapeGeometry(sh), mark.down));
}

function leaderArrow(group, from, to, mat) {
  const a = V2(from[0], from[1]), b = V2(to[0], to[1]);
  const dir = b.clone().sub(a).normalize();
  const hl = 0.18;
  group.add(rodMesh(a, b.clone().addScaledVector(dir, -hl), 0.011, mat, 8));
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.062, hl, 12), mat);
  cone.position.copy(b.clone().addScaledVector(dir, -hl / 2));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  group.add(cone);
}
leaderArrow(notation, [-1.72, 1.42], [-0.66, 0.18], lead.left);
leaderArrow(notation, [1.30, 2.00], [0.16, 0.82], lead.up);
leaderArrow(notation, [1.42, 1.88], [0.72, 0.17], lead.right);
leaderArrow(notation, [1.24, -1.62], [0.20, -0.70], lead.down);

/* click proxies over the 2D marks */
const DIR2D = { up: [0, 1], right: [1, 0], left: [-1, 0], down: [0, -1] };
function makeProxy(parent, a, b, r, key) {
  const pm = rodMesh(a, b, r, proxyMat(), 8);
  pm.userData.isProxy = true; pm.userData.baseOpacity = 0; pm.userData.active = true;
  pm.raycast = function (rc, its) {
    if (this.userData.active === false) return;
    THREE.Mesh.prototype.raycast.call(this, rc, its);
  };
  parent.add(pm);
  registerInteractive(pm, {
    title: 'C–H bond — ' + BOND_NAME[key],
    body: BOND_TEXT[key] + ' All four C–H bonds in methane are identical; the plain line, dash and wedge are depth cues, not different bond types.',
    tooltip: BOND_NAME[key] + ' — click to highlight',
    onClick: () => selectBond(key)
  });
  return pm;
}
const BOND_NAME = {
  up: 'plain line, in the plane of the page',
  right: 'plain line, in the plane of the page',
  left: 'dashed line, receding behind the page',
  down: 'bold wedge, coming out of the page'
};
const BOND_TEXT = {
  up: 'Drawn as a plain line straight up: this bond lies in the plane of the page.',
  right: 'Drawn as a plain line to the right: this bond also lies in the plane of the page.',
  left: 'Drawn as a short dashed line: this bond recedes behind the page, away from you.',
  down: 'Drawn as a solid wedge that widens away from C: this bond comes out of the page, toward you.'
};
Object.keys(DIR2D).forEach(k => {
  const d = DIR2D[k];
  makeProxy(notation, V2(d[0] * 0.26, d[1] * 0.26), V2(d[0] * 0.98, d[1] * 0.98), 0.21, k);
});

/* ball-and-stick methane */
const model = new THREE.Group();
model.position.copy(P(5.95, 0.15, 0));
model.rotation.y = Math.PI / 4;
panelB.add(model);
const matCmod = new THREE.MeshStandardMaterial({ color: COL.C, roughness: 0.3, metalness: 0.2, transparent: true });
model.add(new THREE.Mesh(new THREE.SphereGeometry(0.45, 44, 30), matCmod));
const DIR3D = { up: [-1, 1, -1], right: [1, 1, 1], left: [1, -1, -1], down: [-1, -1, 1] };
Object.keys(DIR3D).forEach(k => {
  const dir = new THREE.Vector3().fromArray(DIR3D[k]).normalize();
  const end = dir.clone().multiplyScalar(1.02);
  const rm = new THREE.MeshStandardMaterial({ color: COL.rod, roughness: 0.45, metalness: 0.15, transparent: true, emissive: 0x000000 });
  model.add(rodMesh(new THREE.Vector3(0, 0, 0), end, 0.07, rm, 16));
  const hm = new THREE.MeshStandardMaterial({ color: COL.H, roughness: 0.28, metalness: 0.05, transparent: true, emissive: 0x000000 });
  const hs = new THREE.Mesh(new THREE.SphereGeometry(0.30, 34, 24), hm);
  hs.position.copy(end); model.add(hs);
  BONDS[k].rodMat = rm; BONDS[k].hMat = hm;
  makeProxy(model, new THREE.Vector3(0, 0, 0), end.clone().multiplyScalar(1.15), 0.24, k);
});

/* curly brace */
const braceG = new THREE.Group();
braceG.position.copy(P(3.4, -3.05, 0));
panelB.add(braceG); billboards.push(braceG);
{
  const hw = 3.75;
  const half = [[-hw, 0.02], [-hw + 0.10, -0.14], [-hw + 0.19, -0.30], [-hw + 0.24, -0.39],
                [-0.60, -0.41], [-0.36, -0.45], [-0.17, -0.56], [0, -0.74]];
  const pts = half.map(p => new THREE.Vector3(p[0], p[1], 0));
  for (let i = half.length - 2; i >= 0; i--) pts.push(new THREE.Vector3(-half[i][0], half[i][1], 0));
  const bm = new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true });
  braceG.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 140, 0.018, 6, false), bm));
}

