/* ── highlight / selection ──────────────────────────────────────────────── */
let selected = null;
const bondInfoEl = document.getElementById('bondInfo');
function selectBond(name) {
  selected = name;
  Object.keys(BONDS).forEach(k => {
    const b = BONDS[k];
    b.mats.forEach(m => m.color.setHex(COL.blk));
    if (b.rodMat) { b.rodMat.color.setHex(COL.rod); b.rodMat.emissive.setHex(0x000000); }
    if (b.hMat) { b.hMat.emissive.setHex(0x000000); b.hMat.color.setHex(COL.H); }
    b.labels.forEach(e => { e.div.style.color = '#111'; e.div.style.fontWeight = 'normal'; });
    const btn = document.getElementById('bondBtn-' + k);
    if (btn) btn.classList.remove('active');
  });
  if (name && BONDS[name]) {
    const b = BONDS[name];
    b.mats.forEach(m => m.color.setHex(COL.amber));
    if (b.rodMat) { b.rodMat.color.setHex(COL.amber); b.rodMat.emissive.setHex(0x6b3c00); }
    if (b.hMat) { b.hMat.emissive.setHex(0x4a2800); }
    b.labels.forEach(e => { e.div.style.color = '#C46A00'; e.div.style.fontWeight = 'bold'; });
    const btn = document.getElementById('bondBtn-' + name);
    if (btn) btn.classList.add('active');
    bondInfoEl.innerHTML = '<b>' + BOND_NAME[name] + '</b><br>' + BOND_TEXT[name] +
      ' Every C–H bond here is identical (109.5° apart).';
    if (panel !== 'B') setPanel('B');
  } else {
    bondInfoEl.textContent = 'Click a bond mark in the drawing, a rod in the model, or a leader label.';
  }
}

/* ── panel / inscribe state, framing ────────────────────────────────────── */
let panel = 'B';
let inscribeOn = false;
let fadeA = 0.16, fadeB = 1.0, fadeIns = 0.0;
let tgtA = 0.16, tgtB = 1.0, tgtIns = 0.0;

const FOCUS = {
  A: { s: -4.45, y: -0.55, w: 6.4, h: 5.2 },
  B: { s: 3.40, y: -0.55, w: 9.0, h: 7.8 }
};
function zoomFor(f) {
  const z = Math.min(2 * d * aspect * 0.88 / f.w, 2 * d * 0.88 / f.h);
  return Math.max(0.15, Math.min(5, z));
}
let panTween = { t: 1, fromT: new THREE.Vector3(), fromP: new THREE.Vector3(), fromZ: 1, toZ: 1, tgt: new THREE.Vector3() };
function applyFocus(instant) {
  const f = (panel === 'A') ? FOCUS.A : FOCUS.B;
  const tgt = P(f.s, f.y, 0);
  const z = zoomFor(f);
  _labelZoomRef = zoomFor(FOCUS.B);
  if (instant) {
    const off = tgt.clone().sub(controls.target);
    camera.position.add(off);
    controls.target.copy(tgt);
    camera.zoom = z;
    camera.updateProjectionMatrix();
    controls.update();
    panTween.t = 1;
  } else {
    panTween = { t: 0, fromT: controls.target.clone(), fromP: camera.position.clone(), fromZ: camera.zoom, toZ: z, tgt };
  }
}
function setPanel(p) {
  panel = p;
  tgtA = (p === 'A') ? 1 : 0.16;
  tgtB = (p === 'B') ? 1 : 0.16;
  document.getElementById('btnPanelA').classList.toggle('active', p === 'A');
  document.getElementById('btnPanelB').classList.toggle('active', p === 'B');
  applyFocus(false);
}
function setInscribe(on, autoPanel) {
  inscribeOn = on;
  tgtIns = on ? 1 : 0;
  const b = document.getElementById('btnInscribe');
  b.textContent = 'Inscribe CH₄ in the tetrahedron: ' + (on ? 'on' : 'off');
  b.classList.toggle('active', on);
  if (on && autoPanel !== false && panel !== 'A') setPanel('A');
}

/* fading */
function setGroupFade(group, amt) {
  group.traverse(o => {
    if (o.isMesh || o.isLine) {
      const m = o.material;
      if (!m) return;
      const base = (o.userData.baseOpacity !== undefined) ? o.userData.baseOpacity : 1;
      m.transparent = true;
      m.opacity = base * amt;
      m.depthWrite = (base * amt > 0.9);
      o.visible = amt > 0.02;
    }
    if (o.userData.isProxy) { o.visible = true; o.userData.active = amt > 0.5; }
  });
}

/* ── tour ───────────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The solid', narration: 'A regular tetrahedron: four identical triangular faces, four equivalent vertices. The thick front edge and the black solid/dashed interior lines already hint at near versus far.', panel: 'A', insc: false, bond: null },
  { title: 'Carbon at the centre', narration: 'Drop a carbon at the body centre and hydrogens at the four vertices. Every H–C–H angle is 109.5°, and all four bonds are the same length.', panel: 'A', insc: true, bond: null },
  { title: 'Flattening it onto the page', narration: 'The same molecule drawn in two dimensions: two plain lines lie in the page, a dashed line recedes behind it, and a solid wedge comes toward you.', panel: 'B', insc: false, bond: null },
  { title: 'Marks are depth, not bond type', narration: 'Click any label, bond mark, or 3D rod: the flat mark and its counterpart in the ball-and-stick model light up together. All four C–H bonds are identical.', panel: 'B', insc: false, bond: 'left' }
];
let stepIdx = 2;
const tourTitle = document.getElementById('tourTitle');
const tourText = document.getElementById('tourText');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  setPanel(st.panel === 'A' ? 'A' : 'B');
  setInscribe(st.insc, false);
  selectBond(st.bond);
  tourTitle.textContent = (stepIdx + 1) + '. ' + st.title;
  tourText.textContent = st.narration;
}

