  const end = dir.clone().multiplyScalar(1.02);
  const rm = new THREE.MeshStandardMaterial({ color: COL.rod, roughness: 0.45, metalness: 0.15, transparent: true, emissive: 0x000000 });
  model.add(rodMesh(new THREE.Vector3(0, 0, 0), end, 0.07, rm, 16));
  const hm = new THREE.MeshStandardMaterial({ color: COL.H, roughness: 0.28, metalness: 0.05, transparent: true, emissive: 0x000000 });
  const hs = new THREE.Mesh(new THREE.SphereGeometry(0.30, 34, 24), hm);
  hs.position.copy(end); model.add(hs);
  BONDS[k].rodMat = rm; BONDS[k].hMat = hm;
  makeProxy(model, new THREE.Vector3(0, 0, 0), end.clone().multiplyScalar(1.15), 0.24, k);
});

/* curly brace */
const braceG = new THREE.Group();
braceG.position.copy(P(3.4, -3.05, 0));
panelB.add(braceG); billboards.push(braceG);
{
  const hw = 3.75;
  const half = [[-hw, 0.02], [-hw + 0.10, -0.14], [-hw + 0.19, -0.30], [-hw + 0.24, -0.39],
                [-0.60, -0.41], [-0.36, -0.45], [-0.17, -0.56], [0, -0.74]];
  const pts = half.map(p => new THREE.Vector3(p[0], p[1], 0));
  for (let i = half.length - 2; i >= 0; i--) pts.push(new THREE.Vector3(-half[i][0], half[i][1], 0));
  const bm = new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true });
  braceG.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 140, 0.018, 6, false), bm));
}

/* ── camera ─────────────────────────────────────────────────────────────── */
setCameraView({ projection: 'orthographic', axisScreenAngles: { x: 30, z: 30 }, rollDeg: 0, heightFraction: 0.6 });
_userMovedCamera = true;   // we drive framing ourselves from here on

/* ── labels ─────────────────────────────────────────────────────────────── */
function dynLabel(group, local, text, opts, bucket) {
  const world = group.localToWorld(local.clone());
  const e = addLabel(text, world, opts);
  dynLabels.push({ entry: e, group, local: local.clone() });
  bucket.push(e);
  return e;
}
function staticLabel(pos, text, opts, bucket) {
  const e = addLabel(text, pos, opts);
  bucket.push(e);
  return e;
}

/* Panel A */
staticLabel(P(-4.45, -2.95, 0), 'A regular<br>tetrahedron',
  { bold: true, fontSize: '12px' }, labelsA);
const angleLbl = staticLabel(tetra2.localToWorld(angleLabelLocal.clone()), '109.5&deg;',
  { fontSize: '11px', color: '#7a4a00', bold: true }, labelsA);

/* Panel B — atoms */
const serif = 'Georgia, "Times New Roman", serif';
const atomOpt = { fontSize: '17px' };
const lblC = dynLabel(notation, V2(0, 0), 'C', atomOpt, labelsB);
const lblHu = dynLabel(notation, V2(0, 1.14), 'H', atomOpt, labelsB);
const lblHr = dynLabel(notation, V2(1.14, 0), 'H', atomOpt, labelsB);
const lblHl = dynLabel(notation, V2(-1.14, 0), 'H', atomOpt, labelsB);
const lblHd = dynLabel(notation, V2(0, -1.16), 'H', atomOpt, labelsB);
[lblC, lblHu, lblHr, lblHl, lblHd].forEach(e => { e.div.style.fontFamily = serif; });
BONDS.up.labels.push(lblHu);
BONDS.right.labels.push(lblHr);
BONDS.left.labels.push(lblHl);
BONDS.down.labels.push(lblHd);

/* Panel B — leader texts */
const leadOpt = { fontSize: '11.5px' };
const lblLeadLeft = dynLabel(notation, V2(-2.42, 1.78), 'Bond receding<br>into page', leadOpt, labelsB);
const lblLeadPlane = dynLabel(notation, V2(2.02, 2.32), 'Bonds in plane<br>of page', leadOpt, labelsB);
const lblLeadOut = dynLabel(notation, V2(1.96, -1.86), 'Bond coming<br>out of plane', leadOpt, labelsB);
BONDS.left.labels.push(lblLeadLeft);
BONDS.up.labels.push(lblLeadPlane);
BONDS.right.labels.push(lblLeadPlane);
BONDS.down.labels.push(lblLeadOut);

staticLabel(P(3.4, -4.25, 0), 'A tetrahedral<br>carbon atom', { bold: true, fontSize: '12.5px' }, labelsB);

/* clickable leader labels */
function makeLabelClickable(entry, key) {
  entry.div.style.pointerEvents = 'auto';
  entry.div.style.cursor = 'pointer';
  entry.div.addEventListener('click', (ev) => { ev.stopPropagation(); selectBond(key); });
}
makeLabelClickable(lblLeadLeft, 'left');
makeLabelClickable(lblLeadPlane, 'up');
makeLabelClickable(lblLeadOut, 'down');

/* ── highlight / selection ──────────────────────────────────────────────── */
let selected = null;
const bondInfoEl = document.getElementById('bondInfo');
function selectBond(name) {
  selected = name;
  Object.keys(BONDS).forEach(k => {
    const b = BONDS[k];
    b.mats.forEach(m => m.color.setHex(COL.blk));
    if (b.rodMat) { b.rodMat.color.setHex(COL.rod); b.rodMat.emissive.setHex(0x000000); }
    if (b.hMat) { b.hMat.emissive.setHex(0x000000); b.hMat.color.setHex(COL.H); }
    b.labels.forEach(e => { e.div.style.color = '#111'; e.div.style.fontWeight = 'normal'; });
    const btn = document.getElementById('bondBtn-' + k);
    if (btn) btn.classList.remove('active');
  });
  if (name && BONDS[name]) {
    const b = BONDS[name];
    b.mats.forEach(m => m.color.setHex(COL.amber));
    if (b.rodMat) { b.rodMat.color.setHex(COL.amber); b.rodMat.emissive.setHex(0x6b3c00); }
    if (b.hMat) { b.hMat.emissive.setHex(0x4a2800); }
    b.labels.forEach(e => { e.div.style.color = '#C46A00'; e.div.style.fontWeight = 'bold'; });
    const btn = document.getElementById('bondBtn-' + name);
    if (btn) btn.classList.add('active');
    bondInfoEl.innerHTML = '<b>' + BOND_NAME[name] + '</b><br>' + BOND_TEXT[name] +
      ' Every C–H bond here is identical (109.5° apart).';
    if (panel !== 'B') setPanel('B');
  } else {
    bondInfoEl.textContent = 'Click a bond mark in the drawing, a rod in the model, or a leader label.';
  }
}

/* ── panel / inscribe state, framing ────────────────────────────────────── */
let panel = 'B';
let inscribeOn = false;
let fadeA = 0.16, fadeB = 1.0, fadeIns = 0.0;
let tgtA = 0.16, tgtB = 1.0, tgtIns = 0.0;

const FOCUS = {
  A: { s: -4.45, y: -0.55, w: 6.4, h: 5.2 },
  B: { s: 3.40, y: -0.55, w: 9.0, h: 7.8 }
};
function zoomFor(f) {
  const z = Math.min(2 * d * aspect * 0.88 / f.w, 2 * d * 0.88 / f.h);
  return Math.max(0.15, Math.min(5, z));
}
let panTween = { t: 1, fromT: new THREE.Vector3(), fromP: new THREE.Vector3(), fromZ: 1, toZ: 1, tgt: new THREE.Vector3() };
function applyFocus(instant) {
  const f = (panel === 'A') ? FOCUS.A : FOCUS.B;
  const tgt = P(f.s, f.y, 0);
  const z = zoomFor(f);
  _labelZoomRef = zoomFor(FOCUS.B);
  if (instant) {
    const off = tgt.clone().sub(controls.target);
    camera.position.add(off);
    controls.target.copy(tgt);
    camera.zoom = z;
    camera.updateProjectionMatrix();
    controls.update();
    panTween.t = 1;
  } else {
    panTween = { t: 0, fromT: controls.target.clone(), fromP: camera.position.clone(), fromZ: camera.zoom, toZ: z, tgt };
  }
}
function setPanel(p) {
  panel = p;
  tgtA = (p === 'A') ? 1 : 0.16;
  tgtB = (p === 'B') ? 1 : 0.16;
  document.getElementById('btnPanelA').classList.toggle('active', p === 'A');
  document.getElementById('btnPanelB').classList.toggle('active', p === 'B');
  applyFocus(false);
}
function setInscribe(on, autoPanel) {
  inscribeOn = on;
  tgtIns = on ? 1 : 0;
  const b = document.getElementById('btnInscribe');
  b.textContent = 'Inscribe CH₄ in the tetrahedron: ' + (on ? 'on' : 'off');
  b.classList.toggle('active', on);
  if (on && autoPanel !== false && panel !== 'A') setPanel('A');
}

/* fading */
function setGroupFade(group, amt) {
  group.traverse(o => {
    if (o.isMesh || o.isLine) {
      const m = o.material;
      if (!m) return;
      const base = (o.userData.baseOpacity !== undefined) ? o.userData.baseOpacity : 1;
      m.transparent = true;
      m.opacity = base * amt;
      m.depthWrite = (base * amt > 0.9);
      o.visible = amt > 0.02;
    }
    if (o.userData.isProxy) { o.visible = true; o.userData.active = amt > 0.5; }
  });
}

/* ── tour ───────────────────────────────────────────────────────────────── */
const STEPS = [
  { title: 'The solid', narration: 'A regular tetrahedron: four identical triangular faces, four equivalent vertices. The thick front edge and the black solid/dashed interior lines already hint at near versus far.', panel: 'A', insc: false, bond: null },
  { title: 'Carbon at the centre', narration: 'Drop a carbon at the body centre and hydrogens at the four vertices. Every H–C–H angle is 109.5°, and all four bonds are the same length.', panel: 'A', insc: true, bond: null },
  { title: 'Flattening it onto the page', narration: 'The same molecule drawn in two dimensions: two plain lines lie in the page, a dashed line recedes behind it, and a solid wedge comes toward you.', panel: 'B', insc: false, bond: null },
  { title: 'Marks are depth, not bond type', narration: 'Click any label, bond mark, or 3D rod: the flat mark and its counterpart in the ball-and-stick model light up together. All four C–H bonds are identical.', panel: 'B', insc: false, bond: 'left' }
];
let stepIdx = 2;
const tourTitle = document.getElementById('tourTitle');
const tourText = document.getElementById('tourText');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  setPanel(st.panel === 'A' ? 'A' : 'B');
  setInscribe(st.insc, false);
  selectBond(st.bond);
  tourTitle.textContent = (stepIdx + 1) + '. ' + st.title;
  tourText.textContent = st.narration;
}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
document.getElementById('btnPanelA').addEventListener('click', () => setPanel('A'));
document.getElementById('btnPanelB').addEventListener('click', () => setPanel('B'));
document.getElementById('btnInscribe').addEventListener('click', () => setInscribe(!inscribeOn, true));
['up', 'right', 'left', 'down'].forEach(k => {
  document.getElementById('bondBtn-' + k).addEventListener('click', () => selectBond(selected === k ? null : k));
});
document.getElementById('bondBtn-none').addEventListener('click', () => selectBond(null));
document.getElementById('tourPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('tourNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
let playTimer = null;
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; document.getElementById('tourPlay').textContent = 'Play'; document.getElementById('tourPlay').classList.remove('active'); }
}
document.getElementById('tourPlay').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('tourPlay').textContent = 'Pause';
  document.getElementById('tourPlay').classList.add('active');
  playTimer = setInterval(() => goToStep(stepIdx + 1), 5200);
});

/* ── per-frame: billboards, dynamic labels, fades, framing tween ────────── */
function figTick() {
  requestAnimationFrame(figTick);
  for (const g of billboards) g.quaternion.copy(camera.quaternion);
  for (const dl of dynLabels) dl.entry.pos.copy(dl.group.localToWorld(dl.local.clone()));

  fadeA += (tgtA - fadeA) * 0.12;
  fadeB += (tgtB - fadeB) * 0.12;
  fadeIns += (tgtIns - fadeIns) * 0.12;
  setGroupFade(panelA, fadeA);
  setGroupFade(panelB, fadeB);
  const insAmt = fadeA * fadeIns * 0.9;
  inscG.traverse(o => {
    if (o.isMesh && o.material) { o.material.opacity = insAmt; o.material.depthWrite = insAmt > 0.85; o.visible = insAmt > 0.02; }
  });
  labelsA.forEach(e => { e.div.style.opacity = fadeA.toFixed(3); });
  labelsB.forEach(e => { e.div.style.opacity = fadeB.toFixed(3); });
  angleLbl.div.style.opacity = (fadeA * fadeIns).toFixed(3);

  if (panTween.t < 1) {
    panTween.t = Math.min(1, panTween.t + 0.05);
    const e = panTween.t < 0.5 ? 2 * panTween.t * panTween.t : 1 - Math.pow(-2 * panTween.t + 2, 2) / 2;
    const off = panTween.tgt.clone().sub(panTween.fromT).multiplyScalar(e);
    controls.target.copy(panTween.fromT).add(off);
    camera.position.copy(panTween.fromP).add(off);
    camera.zoom = panTween.fromZ + (panTween.toZ - panTween.fromZ) * e;
    camera.updateProjectionMatrix();
  }
}
figTick();

/* keep framing correct as the canvas / dock resizes */
let _refitT = null;
new ResizeObserver(() => {
  clearTimeout(_refitT);
  _refitT = setTimeout(() => { if (canvas.clientWidth && canvas.clientHeight) applyFocus(true); }, 30);
}).observe(canvas);

/* ── initial state ──────────────────────────────────────────────────────── */
setGroupFade(panelA, fadeA);
setGroupFade(panelB, fadeB);
setPanel('B');
setInscribe(false, false);
selectBond(null);
applyFocus(true);
goToStep(2);
// @FIGURE_CODE_END

