  left: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true }),
  down: new THREE.MeshBasicMaterial({ color: COL.blk, transparent: true })
};
const BONDS = {
  up: { mats: [mark.up, lead.up], labels: [], rodMat: null, hMat: null },
