}
function staticLabel(pos, text, opts, bucket) {
  const e = addLabel(text, pos, opts);
  bucket.push(e);
  return e;
}

/* Panel A */
staticLabel(P(-4.6, -2.45, 0), 'A regular<br>tetrahedron', { bold: true, fontSize: '14px' }, labelsA);
const angleLbl = staticLabel(tetra2.localToWorld(angleLabelLocal.clone()), '109.5&deg;',
  { fontSize: '12px', color: '#8a5000', bold: true }, labelsA);

/* Panel B — atoms */
const serif = 'Georgia, "Times New Roman", serif';
const atomOpt = { fontSize: '19px' };
const lblC = dynLabel(notation, V2(0, 0), 'C', atomOpt, labelsB);
const lblHu = dynLabel(notation, V2(0, 1.16), 'H', atomOpt, labelsB);
