/* ── panel / inscribe state, framing ────────────────────────────────────── */
let panel = 'ALL';
let inscribeOn = false;
let fadeA = 1, fadeB = 1, fadeIns = 0;
let tgtA = 1, tgtB = 1, tgtIns = 0;

const FOCUS = {
  ALL: { s: 0.20, y: -0.45, w: 15.2, h: 7.9 },
  A: { s: -4.60, y: -0.70, w: 7.0, h: 5.6 },
  B: { s: 3.65, y: -0.75, w: 9.8, h: 7.6 }
};
function zoomFor(f) {
  const z = Math.min(2 * d * aspect * 0.90 / f.w, 2 * d * 0.90 / f.h);
  return Math.max(0.15, Math.min(5, z));
}
let panTween = { t: 1, fromT: new THREE.Vector3(), fromP: new THREE.Vector3(), fromZ: 1, toZ: 1, tgt: new THREE.Vector3() };
function applyFocus(instant) {
  const f = FOCUS[panel] || FOCUS.ALL;
