  } else {
    panTween = { t: 0, fromT: controls.target.clone(), fromP: camera.position.clone(), fromZ: camera.zoom, toZ: z, tgt };
  }
}
function setPanel(p) {
  panel = p;
  tgtA = (p === 'A' || p === 'ALL') ? 1 : 0;
  tgtB = (p === 'B' || p === 'ALL') ? 1 : 0;
