  setPanel(st.panel);
  setInscribe(st.insc, false);
  selectBond(st.bond);
  tourTitle.textContent = (stepIdx + 1) + '. ' + st.title;
  tourText.textContent = st.narration;
}

/* ── UI wiring ──────────────────────────────────────────────────────────── */
document.getElementById('btnPanelAll').addEventListener('click', () => setPanel('ALL'));
document.getElementById('btnPanelA').addEventListener('click', () => setPanel('A'));
document.getElementById('btnPanelB').addEventListener('click', () => setPanel('B'));
document.getElementById('btnInscribe').addEventListener('click', () => setInscribe(!inscribeOn, true));
['up', 'right', 'left', 'down'].forEach(k => {
  document.getElementById('bondBtn-' + k).addEventListener('click', () => selectBond(selected === k ? null : k));
});
document.getElementById('bondBtn-none').addEventListener('click', () => selectBond(null));
document.getElementById('tourPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('tourNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });
let playTimer = null;
function stopPlay() {
  if (playTimer) {
    clearInterval(playTimer); playTimer = null;
    document.getElementById('tourPlay').textContent = 'Play';
    document.getElementById('tourPlay').classList.remove('active');
  }
}
document.getElementById('tourPlay').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('tourPlay').textContent = 'Pause';
  document.getElementById('tourPlay').classList.add('active');
  playTimer = setInterval(() => goToStep(stepIdx + 1), 5400);
});

/* ── per-frame: billboards, dynamic labels, fades, framing tween ────────── */
function figTick() {
  requestAnimationFrame(figTick);
  for (const g of billboards) g.quaternion.copy(camera.quaternion);
  for (const dl of dynLabels) dl.entry.pos.copy(dl.group.localToWorld(dl.local.clone()));

  fadeA += (tgtA - fadeA) * 0.12;
  fadeB += (tgtB - fadeB) * 0.12;
  fadeIns += (tgtIns - fadeIns) * 0.12;
  if (Math.abs(tgtA - fadeA) < 0.004) fadeA = tgtA;
  if (Math.abs(tgtB - fadeB) < 0.004) fadeB = tgtB;
  if (Math.abs(tgtIns - fadeIns) < 0.004) fadeIns = tgtIns;
  setGroupFade(panelA, fadeA);
  setGroupFade(panelB, fadeB);
  const insAmt = fadeA * fadeIns * 0.92;
  inscG.traverse(o => {
    if (o.isMesh && o.material) { o.material.opacity = insAmt; o.material.depthWrite = insAmt > 0.85; o.visible = insAmt > 0.02; }
  });
  labelsA.forEach(e => { e.div.style.opacity = fadeA.toFixed(3); });
  labelsB.forEach(e => { e.div.style.opacity = fadeB.toFixed(3); });
  angleLbl.div.style.opacity = (fadeA * fadeIns).toFixed(3);

  if (panTween.t < 1) {
    panTween.t = Math.min(1, panTween.t + 0.05);
    const e = panTween.t < 0.5 ? 2 * panTween.t * panTween.t : 1 - Math.pow(-2 * panTween.t + 2, 2) / 2;
    const off = panTween.tgt.clone().sub(panTween.fromT).multiplyScalar(e);
    controls.target.copy(panTween.fromT).add(off);
    camera.position.copy(panTween.fromP).add(off);
    camera.zoom = panTween.fromZ + (panTween.toZ - panTween.fromZ) * e;
    camera.updateProjectionMatrix();
  }
}
figTick();

/* keep framing correct as the canvas / dock resizes */
let _refitT = null;
new ResizeObserver(() => {
  clearTimeout(_refitT);
  _refitT = setTimeout(() => { if (canvas.clientWidth && canvas.clientHeight) applyFocus(true); }, 30);
}).observe(canvas);

/* ── initial state ──────────────────────────────────────────────────────── */
setGroupFade(panelA, fadeA);
setGroupFade(panelB, fadeB);
setInscribe(false, false);
selectBond(null);
goToStep(0);
applyFocus(true);
